function handler(input) {
    const data = typeof input === 'string' ? JSON.parse(input) : input;
    const job = data.job || input.job;
    const config = data.config || input.config || {};

    let output = {
        conTypeId: config.conTypeId || null,
        ExternalRef1: job.shipperReference1,
        ExternalRef2: job.shipperReference2,
        From: {
            BusinessName: job.origin.companyName,
            ContactName: job.origin.contact.contactName,
            PhoneNumber: job.origin.contact.phoneRaw,
            Email: job.origin.contact.email,
            Address: {
                StreetAddress: job.origin.address1,
                AdditionalDetails: job.origin.address2,
                Locality: job.origin.city,
                StateOrProvince: job.origin.state,
                PostalCode: job.origin.postCode,
                Country: job.origin.countryCode
            }
        },
        To: {
            BusinessName: job.destination.companyName,
            ContactName: job.destination.contact.contactName,
            PhoneNumber: job.destination.contact.phoneRaw,
            Email: job.destination.contact.email,
            Address: {
                StreetAddress: job.destination.address1,
                AdditionalDetails: job.destination.address2,
                Locality: job.destination.city,
                StateOrProvince: job.destination.state,
                PostalCode: job.destination.postCode,
                Country: job.destination.countryCode
            }
        },
        pickupTypeId: 2,
        Items: []
    };

    if (job.origin.countryCode == "NZ" && job.destination.countryCode == "NZ") {
        let pickupInstructions = "PICKUP: " + (job.pickupInstructions != null ? job.pickupInstructions : "");
        if (job.depotDropOff) {
            pickupInstructions += " DEPOT DROP OFF";
        }
        if (job.origin.tailLift) {
            pickupInstructions += " TAIL LIFT REQUIRED";
        }

        let deliveryInstructions = "DELIVER: " + (job.deliveryInstructions != null ? job.deliveryInstructions : "");
        if (job.depotCollection) {
            deliveryInstructions += " DEPOT COLLECT";
        }
        if (job.destination.tailLift) {
            deliveryInstructions += " TAIL LIFT REQUIRED";
        }
        output.InstructionsPublic = pickupInstructions + " " + deliveryInstructions;
    } else {
        output.InstructionsPublic = job.pickupAndtailLiftInstructions + " " + job.deliveryAndtailInstructions;
    }
    if (job.atl) {
        output.Services = [];
        output.Services.push({ServiceCode: 'DELOPT', ServiceItemCode: 'ATL'});
    } else {
        output.Services = [];
        output.Services.push({ServiceCode: 'DELOPT', ServiceItemCode: 'SGR'});
    }
    if (job.customFields != null && job.customFields.agentId != null) {
        output.To.AgentId = job.customFields.agentId;
    }
    for (let item of job.items.items) {
        let itm = {
            Quantity: item.quantity,
            WeightDead: item.weightKG,
            WeightCubic: item.itemVolumeM3,
            Length: item.lengthCM,
            Width: item.widthCM,
            Height: item.heightCM,
            reference: item.id.toString()
        };
        let itemReference = item.references != null && item.references.length > 0 ? item.references[0].value : null;
        if (itemReference != null) {
            itm.reference = itemReference + "|" + item.id.toString();
        }
        itm.PackageType = 'P';
        output.Items.push(itm);
    }
    if (job.customFields != null && job.customFields.trackingnumber != null) {
        output.Items[0].label = job.customFields.trackingnumber;
    } else if (job.customFields != null && job.customFields.trackingNumber != null) {
        output.Items[0].label = job.customFields.trackingNumber;
    }
    if (config.ServiceItemCode != null) {
        output.Services[0].ServiceItemCode = config.ServiceItemCode;
    }

    return output;
}

function handler(input) {
    const data = typeof input === 'string' ? JSON.parse(input) : input;
    const job = data.job || input.job;
    const response = data.response || tasks.send_consignment.output.data || input.response;

    let output = [];
    let itemIndex = 0;
    let responseMap = response.items.reduce((acc, current) => {
        let itemId = current.reference;
        if (current.reference.includes("|")) {
            itemId = current.reference.split("|")[1];
        }
        if (!acc[itemId]) {
            acc[itemId] = [];
        }
        acc[itemId].push(current);
        return acc;
    }, {});
    for (let item of job.items.items) {
        let itemId = item.id;
        for (let i = 0; i < item.quantity; i++) {
            let out = {};
            let responseObj = responseMap[itemId];
            out.itemId = itemId;
            out.itemNumber = responseObj[i].conItemId;
            out.labelNumber = responseObj[i].label;
            output.push(out);
        }
    }
    return output;
}
